function proposal(c:Cfg,cat:any,m:any,kind:'ordinary'|'targeted-promotion'='ordinary'){const item=m.documents[0],id=controllerId(c),key=hash(canonical({controller_id:id,document_version_id:item.document_version_id,source_version:item.source_version,enrichment_row_sha256:item.enrichment_row_sha256,extractor_version:item.extractor_version,...(kind==='ordinary'?{}:{selection:kind})}));return{controller_id:id,key,catalog_snapshot_sha256:hash(canonical({source:c.catalog_source_sha256,etag:cat.catalogEtag,createdAt:cat.createdAt})),catalog_source_sha256:c.catalog_source_sha256,catalog_etag_sha256:hash(cat.catalogEtag),manifest:m,run:run(c,m.manifest_sha256,kind),max_documents:1,document_ordinal:0,paid_fallback:false,requires_review:true};}
