 route('GET','/config',async(_r,_p,c)=>({enabled:live(c,d),cohort_id:c.cohort_id,controller:{catalogSourceSha256:c.catalog_source_sha256,purpose:c.purpose,runVersion:c.run_version,batchSize:c.batch_size},policy_sha256:c.policy_sha256,max_admissions:c.max_admissions,...(c.max_active_admissions===1?{}:{max_active_admissions:c.max_active_admissions})}));
